"""Build the standalone marketing page without changing CRM routes."""
import json
from html import escape
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DEST = ROOT / 'products'
products = json.loads((DEST / 'data.json').read_text(encoding='utf8'))
external = 'target="_blank" rel="noopener noreferrer"'
arrow = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14M13 6l6 6-6 6"/></svg>'
tabs = ''.join(f'<button role="tab" id="tab-{p["id"]}" aria-controls="product-{p["id"]}" aria-selected="{str(i==0).lower()}" tabindex="{0 if i==0 else -1}" data-product="{p["id"]}"><span>{p["name"]}</span></button>' for i,p in enumerate(products))
panels = []
for i,p in enumerate(products):
    pid = p['id']
    feature_tabs = ''.join(f'<button role="tab" id="feature-tab-{pid}-{j}" aria-controls="feature-{pid}-{j}" aria-selected="{str(j==0).lower()}" tabindex="{0 if j==0 else -1}" data-feature="{j}"><span class="feature-number">0{j+1}</span><span>{escape(f["name"])}</span>{arrow}</button>' for j,f in enumerate(p['features']))
    features = []
    for j,f in enumerate(p['features']):
        features.append(f'''<div class="feature-view" role="tabpanel" id="feature-{pid}-{j}" aria-labelledby="feature-tab-{pid}-{j}" {'' if j==0 else 'hidden'}>
          <div class="feature-heading"><h3>{escape(f['title'])}</h3><p>{escape(f['description'])}</p></div>
          <figure><button class="screen-zoom" data-zoom="assets/ui/{f['image']}" data-caption="{escape(f['caption'],quote=True)}" aria-label="{escape(f['name'])} 화면 크게 보기"><img src="assets/ui/{f['image']}" alt="{escape(f['caption'],quote=True)}" width="{f["width"]}" height="{f["height"]}" style="--screen-width:{f["width"]}px" loading="lazy"><span>화면 크게 보기 <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/></svg></span></button><figcaption><span>{escape(f['caption'])}</span><a href="{escape(f['source'],quote=True)}" {external}>자료 원문 ↗</a></figcaption></figure>
        </div>''')
    next_product = products[(i+1)%len(products)]
    panels.append(f'''<section class="product-panel" role="tabpanel" id="product-{pid}" aria-labelledby="tab-{pid}" data-id="{pid}" {'' if i==0 else 'hidden'}>
      <div class="product-stage" data-motion-stage>
        <div class="stage-watermark" aria-hidden="true">{p['name'].replace(' 비영리','')}</div>
        <div class="stage-inner wrap">
          <div class="stage-copy"><span class="eyebrow">{p['eyebrow']}</span><div class="product-name">{p['name']}</div><h2>{p['title']}</h2><p>{escape(p['description'])}</p><div class="product-tags">{''.join(f'<span>{escape(t)}</span>' for t in p['tags'])}</div><a class="text-link" href="#features-{pid}" data-jump-features>기능과 화면 살펴보기 {arrow}</a></div>
          <div class="stage-art"><div class="art-ring" aria-hidden="true"></div><img class="stage-asset {'wide-asset' if pid=='ifrs18' else ''}" src="assets/{p['asset']}" alt="{escape(p['name'])} 3D 제품 비주얼" width="600" height="600"><span class="orbit-tag" aria-hidden="true">{'NONPROFIT' if pid=='nonprofit' else 'CONNECTED BUSINESS'}</span></div>
        </div>
        <div class="stage-bottom wrap"><span>{escape(p['audience'])}</span><button class="motion-skip" data-jump-features>소개 건너뛰기 ↓</button><span class="stage-step"><b>0{i+1}</b> / 06</span></div><div class="stage-progress" aria-hidden="true"><span></span></div>
      </div>
      <div class="features-section wrap" id="features-{pid}"><div class="section-intro"><span class="eyebrow">PRODUCT IN ACTION</span><h2>실제 화면으로 만나는<br>{escape(p['name'])}.</h2><p>기능을 선택해 업무가 어떻게 이어지는지 확인하세요.</p></div>
        <div class="feature-layout"><div class="feature-sidebar"><div class="feature-tabs" role="tablist" aria-label="{escape(p['name'])} 기능" aria-orientation="vertical">{feature_tabs}</div><a class="source-link" href="{escape(p.get('brochure',p['source']),quote=True)}" {external}>{'제품 제안서 보기' if p.get('brochure') else '제품 소개 자세히 보기'} ↗</a></div><div class="feature-content">{''.join(features)}</div></div>
        <p class="product-note">화면은 제품 소개 자료의 예시이며, 도입 모듈·버전·설정에 따라 제공 기능과 화면이 달라질 수 있습니다.</p>
        <button class="next-product" data-next="{next_product['id']}"><span>다음 제품도 살펴보세요</span><strong>{next_product['name']}</strong>{arrow}</button>
      </div>
    </section>''')

